	if expiryMillis != nil {
		exp := time.Now().Add(time.Duration(*expiryMillis) * time.Millisecond)
		val.exp = &exp
	}
	s.data[key] = val
}

func (s *Storage) Del(keys []string) int {
	s.mu.Lock()
	defer s.mu.Unlock()

	deleted := 0
	for _, key := range keys {
		if _, exists := s.get(key); exists {
			delete(s.data, key)
			deleted++
		}
	}
	return deleted
