type Client struct {
	conn net.Conn
	rd   *bufio.Reader
	wr   *bufio.Writer
	storage *Storage
}

func NewClient(conn net.Conn, storage *Storage) *Client {
	return &Client{
		conn: conn,
		rd:   bufio.NewReader(conn),
		wr:   bufio.NewWriter(conn),
		storage: storage,
	}
}

func (c *Client) Close() {
	c.conn.Close()
}

func (c *Client) readLine() ([]byte, error) {
	line, err := c.rd.ReadBytes('\n')
	if err != nil {
