	conn.Write([]byte("*7\r\n$3\r\nSET\r\n$3\r\nkey\r\n$5\r\nvalue\r\n$2\r\nEX\r\n$1\r\n1\r\n$2\r\nPX\r\n$3\r\n100\r\n"))
