type Storage struct {
	mu    sync.RWMutex
	data  map[string]*Value
}

type Value struct {
	data []byte
	exp  *time.Time // nil means no expiry
}

func NewStorage() *Storage {
	return &Storage{
		data: make(map[string]*Value),
	}
