func (s *Storage) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	val, exists := s.data[key]
	s.mu.RUnlock()

	if !exists {
		return nil, false
	}

	// Check expiry (lazy expiry)
	if val.exp != nil && time.Now().After(*val.exp) {
		s.mu.Lock()
		// Check again under write lock in case it was changed
		val, exists = s.data[key]
		if exists && val.exp != nil && time.Now().After(*val.exp) {
			delete(s.data, key)
		}
		s.mu.Unlock()
		return nil, false
	}

	return val.data, true
}

func (s *Storage) Set(key string, value []byte, expiryMillis *int64) {
	s.mu.Lock()
	defer s.mu.Unlock()

